-- Enrich Course 2 Lesson 2 with source-attested root, prefix and suffix examples.
-- Haig (2018), Table 7, p. 115; Haig & Öpengin (2018), pp. 168-169.
DO $migration$
DECLARE affected integer;
BEGIN
  UPDATE public.lesson_content
  SET content_html = $new$<section class="klesson-card"><h2>١. ڕەگ، بنەڕەت و بنەی وشە</h2><p><strong>ڕەگ</strong> یەکەی ناوەندیی وشەیە و بنەمای واتایی دەگرێتەوە. <strong>بنەڕەت</strong> ئەو فۆڕمەیە کە مۆرفیمێک پێوە دەبەسترێت؛ <strong>بنەی وشە</strong> ئەو فۆڕمەیە کە نیشانەی شێوەگۆڕیی ڕێزمانی وەردەگرێت. ئەم سێ زاراوەیە هەمیشە یەک مانا نادەن و نابێت بە یەکتر بگۆڕدرێن.</p></section>
<section class="klesson-card"><h2>٢. پێشگر و پاشگر</h2><p><strong>پێشگر</strong> مۆرفیمێکی بەستراوە کە لە پێش بنەی وشە دێت؛ <strong>پاشگر</strong> لە دواوەی بنەی وشە دەبەسترێت. شوێنی مۆرفیم بە تەنیا بۆ ناسینەوەی کارکردییەکەی بەس نییە؛ پێویستە بەڵگەی ڕێزمانی و فۆڕمە هاوبەشەکانیش بپشکنرێن.</p></section>
<section class="klesson-card"><h2>٣. نموونە سەرچاوەدارەکان لە کورمانجیی ستاندارد</h2><table><thead><tr><th>فۆڕم</th><th>شیکردنەوە</th><th>کارکرد</th></tr></thead><tbody><tr><td><code>gund-ek</code></td><td><code>gund</code> + <code>-ek</code></td><td>ڕەگ + پاشگری نادیاریی تاک</td></tr><tr><td><code>di-</code></td><td>پێشگری کردار</td><td>نیشاندانی indicative present</td></tr><tr><td><code>bi-</code></td><td>پێشگری کردار</td><td>نیشاندانی subjunctive</td></tr></tbody></table><p>لە نموونەی <code>gund-ek</code>دا، <code>gund</code> «گوند» و <code>-ek</code> نیشانەی نادیاریی تاکە. Haig (2018، خشتەی ٧، لاپەڕەی ١١٥) فۆڕمی <code>gund-ek</code> بۆ نێری تاکی نادیار لە حاڵەتی ڕاستەوخۆ تۆمار دەکات.</p><p>Haig و Öpengin (2018، لاپەڕەکانی ١٦٨–١٦٩) پێشگرە کردارەکانی <code>di-</code> بۆ indicative present و <code>bi-</code> بۆ subjunctive جیا دەکەنەوە. لە هەندێک ژینگەی دەنگیدا، بزوێنی ناو پێشگرەکە دەتوانێت بسڕدرێتەوە؛ بۆیە لە نموونەی شیکردنەوەدا فۆڕمی بنەڕەتیی <code>di-</code>/<code>bi-</code> لە فۆڕمی دەنگدراوی <code>d-</code>/<code>b-</code> جیا دەکرێتەوە.</p></section>
<section class="klesson-card"><h2>٤. شیکردنەوەی نموونە: مۆرفیمی ئازاد و بەستراو</h2><p><code>gund</code> دەتوانێت وەک وشەیەکی سەربەخۆ بەکاربهێنرێت؛ بەڵام <code>-ek</code> بە تەنیا وشە نییە و دەبێت بە ناوەکەوە ببەسترێت. بۆیە لەم نموونەیەدا <code>gund</code> ڕەگ و مۆرفیمی ئازادە، و <code>-ek</code> مۆرفیمی بەستراوی پاشگرە.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note"><code>di-</code> و <code>bi-</code> لەم نموونانەدا پێشگری شێوەگۆڕیی ڕێزمانیی کردارین؛ نابێت بە نموونەی وشەسازیی داڕشتنی وشەی نوێ بناسرێن. هەروەها <code>li</code> و <code>ji</code> لە خشتەی سەرچاوەدا وەک پێشئاوەڵ (preposition) هاتوون، نەک پێشگر. لە هەر شیکردنەوەیەکدا فۆڕمی کورمانجی و سنووری شێوەزار بپارێزە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>جیاوازی ڕەگ و بنەی وشە چییە؟</li><li>لە <code>gund-ek</code>دا ڕەگ و پاشگر کامانەن؟</li><li><code>di-</code> و <code>bi-</code> لە کورمانجیی ستاندارددا چ کارکردێکیان هەیە؟</li><li>بۆچی نابێت <code>di-</code> و <code>bi-</code> بە نموونەی وشەسازی دابنرێن؟</li></ol></section>
<section class="klesson-card"><h2>وەڵامی نموونەیی</h2><ol><li>ڕەگ بنەمای واتایی وشەیە؛ بنەی وشە ئەو فۆڕمەیە کە نیشانەی شێوەگۆڕی وەردەگرێت.</li><li>لە <code>gund-ek</code>دا <code>gund</code> ڕەگ و <code>-ek</code> پاشگری نادیاریی تاکە.</li><li><code>di-</code> indicative present و <code>bi-</code> subjunctive نیشان دەدەن.</li><li>چونکە ئەم پێشگرانە کارکردی ڕێزمانیی کردار دەردەبڕن و لە نموونە سەرچاوەدارەکەدا وشەی نوێ دروست ناکەن.</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. Table 7, p. 115. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Haig, Geoffrey & Ergin Öpengin. (2018). “Kurmanji Kurdish in Turkey: Structure, varieties and status.” pp. 156–214. See pp. 168–169 for verbal prefixes <code>di-</code> and <code>bi-</code>. <a href="https://www.uni-bamberg.de/fileadmin/aspra/06_Team/Publications_and_CV/HaigOepengin2018_Kurmanji_Kurdish_.pdf" target="_blank" rel="noopener">PDF — University of Bamberg</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>$new$,
      updated_at = now()
  WHERE lesson_key = 'kurmanji-course-2-lesson-02.html'
    AND course_id = 'kurmanji-course-2'
    AND content_html = $old$<section class="klesson-card"><h2>١. ڕەگ و بنەڕەت</h2><p>لە پشکنینی مۆرفۆلۆژیدا، ڕەگ و بنەڕەت هەندێک جار بە مانای جیاواز بەکاردێن: ڕەگ یەکەی بنەڕەتییە، بەڵام بنەڕەت دەتوانێت فۆڕمێک بێت کە پاشگر یان پێشگر وەردەگرێت. لە توێژینەوەدا پەیویستە پێناسەی بەکارهاتوو ڕون بکرێتەوە.</p></section><section class="klesson-card"><h2>٢. پێشگر و پاشگر</h2><p>پێشگر لە پێش بنەڕەتەوە دێت و پاشگر لە دواوەیەوە. بۆ نمونە، -ek لە ناوی کورمانجی‌دا پاشگرێکی ناسراوە کە لە زۆر سیاقێکدا نادیاریی تاک نیشان دەدات؛ بەڵام نابێت بۆ هەر وشەیەک بە شێوەیەکی ئۆتۆماتیکی ئەم شیکردنەوەیە بەکاربهێنرێت.</p></section><section class="klesson-card"><h2>٣. شیکردنەوەی زانستی</h2><p>بۆ هەر وشەیەک، فۆڕمی بنەڕەت، مۆرفیمی زیادکراو و گۆڕانی واتایی یان ڕێزمانی بەڵگەدار بکە. ئەگەر بەشێک لە وشەکان بە بەراورد پشتگیری نەکرێت، بە پێشگری خەیاڵی یان پاشگری خەیاڵی دابنەنرێت.</p></section>
<section class="klesson-card"><h2>تێبینیی مێتۆدی</h2><p class="klesson-note">پێشگر و پاشگر تەنیا بە شوێنیان ناسراو ناکرێن؛ کارکردی ڕێزمانی و بەراوردی وشەکانیش پەیویستە. بۆ جیاوازییە شێوەزارییەکان، سەرچاوەی تایبەت بە ناوچە و سیاقەکە بەراورد بکە.</p></section>
<section class="klesson-card"><h2>پرسیارەکانی پێداچوونەوە</h2><ol><li>ڕەگ چیە؟</li><li>جیاوازی پێشگر و پاشگر چیە؟</li><li>بۆچی پەیویستە وشەکان بەراورد بکرێن؟</li></ol></section>
<section class="klesson-card"><h2>سەرچاوەکان</h2><ul><li>Haig, Geoffrey. (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. (2006). <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> Renas Media. <a href="https://kurdishacademy.org/?page_id=623" target="_blank" rel="noopener">پەڕەی کتێب لە ئەکادێمیای کوردی</a>.</li></ul><p class="klesson-note">نمونە و یاساکان لە چوارچێوەی کورمانجیی ستاندارددا پێشکەش کراون؛ بۆ جیاوازیی شێوەزار و فۆڕمی تایبەت، دەبێت سەرچاوە و سیاق دیاری بکرێن.</p></section>$old$;
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Expected exactly one unchanged Course 2 Lesson 2 row; updated % rows', affected;
  END IF;
END
$migration$;
